export function matCameraVariant(v){return ['ice','rattan','bamboo'].includes(v.fabric)?v.fabric:['ice','rattan','bamboo'].includes(v.matVariant)?v.matVariant:'ice'}
export function matAngleName(angle,fallback){return {detail:'席面特写',reverse:'席底展示',foot:'席面床尾',pillowclose:'席枕特写',drape:'席边包边'}[angle]||fallback}
export function matCameraPrompt(v,angle){
  const variant=matCameraVariant(v);
  const support=' The single sleeping mat is thin, unpadded and supported on the mattress TOP, ending flush at its edges; exposed mattress side remains visible. No duvet, quilt, puffy padding, bedspread or hanging sides. Mat-covered pillow pair stays at the head and may be naturally outside a detail crop.';
  if(angle==='reverse')return 'MAT UNDERSIDE DISPLAY: a contextual medium-close diagonal photograph from the foot corner, gently revealing only a SMALL underside section of the actual mat while the majority stays flat and supported. '+(variant==='bamboo'?'Hard bamboo slats remain straight and rigid; lift only a few connected rows at the real stitching joints. Bending occurs only between slats, never across a solid strip.':variant==='rattan'?'Firm woven rattan forms a restrained broad curve, with flat strips and thin woven backing still recognizable; no sharp crease or soft duvet waves.':'A thin flexible ice-silk corner makes one modest gravity-settled curve, exposing the thin backing and narrow sewn binding without loft.')+' Principal lifted bound edge and its connected surrounding mat must be fully visible with editing space. No broad head-end duvet turnover, floating flap or folded thick quilt.'+support;
  if(angle==='drape')return 'MAT SIDE BINDING DISPLAY: contextual medium-close three-quarter view along at least HALF the long side of the mat. Show a continuous thin bound edge resting flush on mattress top, clearly connected to the flat upper surface, with one complete corner and the exposed mattress side beneath. The important seam and edge stay entirely inside the crop. There is NO hanging mat drape, skirt or blanket hem.'+support;
  if(angle==='foot')return 'MAT FOOT EDGE VIEW: slightly elevated camera centered near the foot, photographing the LOWER HALF of the sleeping mat and FULL foot-edge width, both bound foot corners and enough connected upper surface. Thin binding rests flush on mattress top with the real mattress side below, and usable room around the edge. No cropped-off corner, hanging quilt hem or puffy roll.'+support;
  if(angle==='pillowclose')return 'MATCHING MAT PILLOWCASE VIEW: contextual medium-close 30-45-degree photograph of the TWO rectangular low-profile sleeping pillows at the head, enclosed in matching mat pillowcases. Both covers show the selected mat weave or bamboo-strip construction, ordinary narrow bound seams and natural contact with the flat mat. Focus on their surface and binding; retain part of connected mat for orientation. Do not substitute smooth white cotton pillows, introduce extra cushions or add a duvet.'+support;
  if(angle==='detail')return 'MAT SURFACE TEXTURE VIEW: contextual medium-close photograph with 85-100 mm equivalent perspective, about 25-45 degrees to the local flat mat surface. Focus on the actual selected '+(variant==='bamboo'?'straight hard bamboo slats, grain, stitching strings and a thin bound seam':variant==='rattan'?'tight over-under flat rattan strips and natural basket weave beside narrow binding':'fine tight ice-silk woven mesh and narrow woven binding')+'. Keep the main texture sharp and the surrounding continuous supported mat visible, principal detail about 50-65% of frame. No invented fabric wrinkles, quilt stitches, puffiness or broad soft fold.'+support;
  return '';
}
export function cameraAtlasFor(v){if(v.product==='pillowcore')return {file:'pillowcore-'+pillowcoreVariant(v)+'-angles.svg',cols:4,rows:3,cells:[...cells]};const key=v.product==='mattress'?'mattress-'+mattressVariant(v):v.product==='blanket'?'blanket-'+blanketVariant(v):v.product==='sleepbag'?'sleepbag-'+sleepbagVariant(v):v.product==='set'?'set':v.product==='quilt'?'quilt-'+(v.quiltSeason||(v.size?.includes('夏凉被')?'summer':'winter')):v.product==='sheet'?'sheet-'+(v.sheetVariant||(v.size?.includes('夹棉')?'quilted':v.size?.includes('床笠')?'fitted':'flat')):v.product==='mat'?'mat-'+matCameraVariant(v):'';return cameraAtlases[key]||null}
export function cameraCellFor(v,angle){const atlas=cameraAtlasFor(v),index=(atlas?.angleIds||cameraAngleIds).indexOf(angle);return atlas&&index>=0?atlas.cells[index]:null}
export function matchingPillowRule(v){if(v.product==='set')return ''; if(v.product==='mat')return ' REQUIRED MAT PILLOW PAIR: include exactly TWO low-profile rectangular sleeping pillows enclosed in matching MAT PILLOWCASES at the head of the bed. Their surfaces and narrow binding use the same selected ice-silk weave, rattan strips or stitched bamboo-slat construction as the main mat. '+((v.imageBBytes||v.imageB)?'Both mat pillowcase FRONTS use original fabric A and REVERSES use fabric B.':'Both mat pillowcases use original fabric A on front, reverse and bound edges.')+' Keep both recognizable in complete-product views; detail crops can naturally exclude them without changing the product setup. No smooth plain cotton substitutes, extra cushions, duvet or blanket.';if(v.product==='sleepbag')return ' REQUIRED UNDERSIDE PILLOW: exactly ONE ordinary plain standard pillow is slid into the same-width sleeve that is sewn on the BACK of the bottom panel along the head edge, so the pillow sits UNDERNEATH the bottom panel and the sleeper head rests on the bag fabric itself. The pillow body stays plain neutral, never a printed or patterned pillowcase, because the uploaded print belongs to the bag fabric only. In full-product views the pillow reads as a soft bulge under the head end of the bag and the sleeve mouth stays hidden; the underside sleeve is shown only at its dedicated close-up angle. No elastic corner straps, no drawstring pouch, no second pillow, no duvet, no bedspread and no added bedding.';if(!['set','quilt','sheet','mattress'].includes(v.product))return '';const hasB=!!(v.imageBBytes||v.imageB);return ' REQUIRED MATCHING PILLOW PAIR: include exactly TWO standard rectangular sleeping pillows with matching removable pillowcases, softly filled and resting naturally at the head of the bed. A slightly relaxed asymmetric tilt/overlap or neat aligned pair is acceptable; keep both clearly recognizable in complete-product views. They are styling companions to the selected main product, not a reason to add an extra duvet, bed sheet, topper or third cushion. '+(hasB?'Both pillowcase FRONTS use original fabric A and REVERSES use fabric B, no swapped sides, no sample-white pillowcases.':'Both pillowcases use original fabric A on front, reverse and sewn edges, no sample-white or plain coordinating pillowcases.')+' Pillow pair stays at the head of the bed in every view; detail crops can naturally exclude it without deleting it from the product setup. Never force two pillows into a corner/hem detail or put them at the foot. Preserve ordinary pillowcase seams unless compatible craft is explicitly chosen. This required pair takes precedence over any old generic instruction to exclude pillows.'}
export function cameraFramingRule(angle,v={}){
  if(v.product==='pillowcore')return ' PILLOW FRAMING: preserve the selected single pillow outline and support; no extra bedding, full views retain clean margins, details retain connected shell.';
  if(v.product==='set')return setCameraFraming(angle);
  if(['mattress','blanket','sleepbag'].includes(v.product)){const corner=angle==='reverse'&&v.product==='mattress'&&mattressVariant(v)!=='foam';return !corner&&['side','front','top','left','right','low','wide','reverse'].includes(angle)?' EDITING SPACE: entire SINGLE selected main product '+(v.product==='mattress'?'and required head-end pillow pair ':'')+'inside canvas, '+(angle==='wide'?'40-50%':'60-70%')+' coverage with 12-18% useful margins around all essential corners. '+(v.product==='mattress'?'Exactly two matching sleeping pillows at head; no extra pillows or additional bedding. ':v.product==='sleepbag'?'Exactly one plain pillow slid into the sleeve on the BACK of the bottom panel, staying underneath the bag fabric; no elastic straps, no drawstring pouch, no duvet or added bedding. ':'No pillow or additional bedding. ')+'No fisheye or stretching. Preserve current selected viewpoint and subtype; only a foam pad underside view stands upright on its long edge.':' EDITING SPACE FOR DETAILS: contextual medium-close detail 50-65% coverage with connected product and usable margins. Foot view shows lower HALF and FULL foot width; side view shows at least half the long edge. For soft mattress-pad reverse show ONLY a small real lifted corner, majority flat. Head-end pillow pair may remain naturally outside this detail crop. No cut-off principal corner.';}
  const fittedCorner=angle==='reverse'&&v.product==='sheet'&&(v.sheetVariant||(v.size?.includes('夹棉')?'quilted':v.size?.includes('床笠')?'fitted':'flat'))!=='flat';
  const matCorner=angle==='reverse'&&v.product==='mat';
  if(!fittedCorner&&!matCorner&&['side','front','top','left','right','low','wide','reverse'].includes(angle))return ' EDITING SPACE: step the camera back and keep the entire selected product and its included pillow pair comfortably inside the canvas. Main-product footprint about '+(angle==='wide'?'40-50%':'60-70%')+' of frame width/height, with roughly 12-18% clean usable room around essential corners, bound edges and pillow tops. Never clip the foot edge, side corner or pillow. Overhead is still vertical 90 degrees; low is still near mattress height. Preserve selected perspective, original print and natural contact shadows; no fisheye or stretching to manufacture margin.';
  return ' EDITING SPACE FOR DETAILS: use a contextual medium-close composition, not an extreme edge-to-edge macro. The requested cloth/hem/corner/side detail occupies about 50-65% of the canvas with surrounding connected textile, support and 12-18% editable space around the important seam/edge. Foot view includes the lower HALF and full foot width; side-edge view includes at least half the long side and the top-to-side transition. Keep actual selected weave sharp enough to inspect. Do not crop away the principal seam or corner; the head-end pillow pair may remain naturally outside this detail crop.';
}
export function cameraReferenceRule(v,angle,imageNumber){
  if(v.product==='pillowcore')return ' Image '+imageNumber+' is a PILLOW STRUCTURE DIAGRAM used for camera orientation only, not a photograph or pattern/material/room source. Generate one photorealistic pillow insert with the selected core and original A/B shell; never copy diagram colors, lines or labels.';
  if(v.product==='set')return ' Image '+imageNumber+' is the CAMERA AND POSE reference for ['+angle+']. Borrow only its camera position, viewing direction, perspective, crop and bedding pose. Ignore its pillow count and positions; use the current creative styling within the product limit. Ignore sample print, colors, texture, room and unselected craft. Apply current scene and selected construction; never render a contact sheet.';
  const setFront=v.product==='set'&&angle==='front'?' Approved four-piece frontal reference: borrow only its centered slightly elevated foot-end camera, two head pillows, broad soft head-end duvet turnover and independently hanging sheet. Do not copy its plaid, teddy patches, lettering, solid blue color or bedroom; apply uploaded A/B and all selected crafts, material and scene. ':'';
  if(v.product==='blanket')return ' Image '+imageNumber+' is the CAMERA COMPOSITION reference for this exact selected angle '+angle+'. Use its viewpoint, product pose, crop and editable margins ONLY. This is one blanket photo, not a fabric, texture, color or room source. Replace EVERY visible product textile with authoritative uploaded A/B print and original color. Never copy sample ivory/grey/green, weave, quilting absent from the selected structure, or other demonstration motifs. Current selected scene, material and any explicitly chosen construction remain authoritative. Include this SINGLE unfilled blanket with neutral furniture and no pillow or added bedding. No collage. '+(v.promptSections?.placement??singleProductPlacement(v));
  if(v.product==='sleepbag')return ' Image '+imageNumber+' is the CAMERA COMPOSITION reference for this exact selected angle '+angle+'. Use its viewpoint, product pose, crop and editable margins ONLY. This is one travel sleeping bag photo, not a fabric, texture, color or room source. Replace EVERY visible product textile with authoritative uploaded A/B print and original color. Never copy sample ivory/grey/green, weave, quilting absent from the selected structure, or other demonstration motifs. Current selected scene, material and any explicitly chosen construction remain authoritative. Include this SINGLE flat TWO-LAYER travel sleeping bag (both long sides sewn only along the lower half, unsewn open upper half, foot-end zipper, underside pillow sleeve) with neutral furniture, one plain pillow slid into the underside sleeve and no added bedding. No collage. '+(v.promptSections?.placement??singleProductPlacement(v));
  if(v.product==='mattress')return ' Image '+imageNumber+' is the CAMERA COMPOSITION reference for this exact selected angle '+angle+'. Use its viewpoint, product pose, crop and editable margins ONLY. This is one mattress photo, not a fabric, texture, color or room source. Replace EVERY visible product textile with authoritative uploaded A/B print and original color. Never copy sample ivory/grey/green, weave, quilting absent from the selected structure, or other demonstration motifs. Current selected scene, material and any explicitly chosen construction remain authoritative. Include this SINGLE main product with neutral furniture; '+matchingPillowRule(v)+' No collage. '+(v.promptSections?.placement??singleProductPlacement(v));
  return setFront+' Image '+imageNumber+' is a CAMERA COMPOSITION AND PILLOW-PLACEMENT reference for this exact selected angle '+angle+', not a fabric/color/material/environment reference. Rephotograph the selected product with its viewpoint, perspective, broad crop, editable margins and relevant pillow arrangement. Its printed or plain demonstration textiles are illustrative only; replace EVERY product textile including both pillowcases with the authoritative uploaded A/B print and base color. NEVER copy its demonstration product color, weave or motif; do not blend its botanical flowers, leaves or any other sample pattern into the uploaded fabric. Do not copy its decor, lamp, wall, room or lighting when they differ from current selected scene/material. Preserve the CURRENT requested scene; geometry/crop only come from this camera reference. Selected product subtype, seasonal thickness and explicit material remain authoritative. Use only this ONE photograph as camera guidance, no contact sheet, collage or split view.';
}

