export function singleProductDirection(product,angle,v={}){if(product==='pillowcore')return pillowcoreDirection(v,angle);return product==='set'?setCameraDirections[angle]:product==='mattress'?mattressDirection(v,angle,singleProductDirections[angle]):product==='blanket'?blanketDirection(v,angle,singleProductDetailDirections.blanket[angle]||singleProductDirections[angle]):product==='sleepbag'?sleepbagDirection(v,angle,singleProductDirections[angle]):null}
export function singleProductAngleName(product,angle,fallback,v={}){return singleProductDirection(product,angle,v)?.name||fallback}
export function singleProductCameraPrompt(v,angle){return singleProductDirection(v.product,angle,v)?.prompt||''}
export function singleProductPrompt(v,zh=false){
  if(v.product==='pillowcore')return pillowcoreProductPrompt(v,zh);
  if(v.product==='mattress')return mattressProductPrompt(v,zh);
  if(v.product==='blanket')return blanketProductPrompt(v,zh);
  if(v.product==='sleepbag')return sleepbagProductPrompt(v,zh);
  return '';
}
export function singleProductPlacement(v,zh=false){
  if(v.product==='pillowcore')return pillowcorePlacement(v,zh);
  if(!['mattress','blanket','sleepbag'].includes(v.product))return '';
  const hasB=!!(v.imageBBytes||v.imageB);
  if(zh)return hasB?(v.product==='mattress'?'床垫顶面和全部侧围用A，底面用B；包边沿用相邻面的花型。':v.product==='sleepbag'?'旅行睡袋上层布外面与底层布躺卧面用A，两片布的真实反面/底面用B，背面枕袋布沿用底层布底面的花型。':'毯子正面用A、反面用B，包边沿用相邻面的花型。')+'只在真实底面/反面展示时露B，不增加其他床品或拼花。'+(v.product==='mattress'?'配拍2只枕套正面A、反面B的睡枕。':v.product==='sleepbag'?'背面枕袋里只放1只素色普通睡枕，不给枕头加印花枕套。':''):'整件产品及所有正反面、侧围和包边均用A，不增加其他花型、素色协调面或床品。'+(v.product==='mattress'?'配拍2只正反面全部用A的睡枕。':v.product==='sleepbag'?'背面枕袋里只放1只素色普通睡枕。':'');
  return hasB?(v.product==='mattress'?'EXACT MATTRESS A/B: TOP and ALL SIDEWALLS use original A; actual BOTTOM uses original B.':v.product==='sleepbag'?'EXACT SLEEPING BAG A/B: the TOP panel outer face and the BOTTOM panel sleeping face use original A; the actual reverse of the top panel and the actual underside of the bottom panel use original B, and the underside pillow sleeve follows the bottom panel underside.':'EXACT BLANKET A/B: FRONT uses original A and actual REVERSE uses original B.')+' Binding follows its adjacent actual surface. Expose B only through the physically correct selected bottom/reverse view; never blend patterns or add bedding.'+(v.product==='mattress'?' Exactly two matching pillowcase FRONTS use original A; their REVERSES use original B. For thin pads, sidewall means ONLY the narrow soft pad edge.':v.product==='sleepbag'?' The single pillow inside the underside sleeve stays plain and neutral, never printed with A or B, and it never becomes a second printed surface.':''):'Only A was supplied: the ENTIRE selected single product, both panels, all front/reverse/underside surfaces, the side seams and the underside pillow sleeve use original A. No other print, coordinating plain surface or additional bedding.'+(v.product==='mattress'?' Both matching pillowcases use original A on front/reverse/edges.':v.product==='sleepbag'?' The single pillow inside the underside sleeve stays plain and neutral, never printed with A.':'');
}
